1: import { CanActivateFn, ActivatedRouteSnapshot, RouterStateSnapshot } from '@angular/router';
2: import { inject } from '@angular/core';
3: import { AlertService } from 'src/app/services/alert.service';
4: 
5: export const authGuard: CanActivateFn = (route: ActivatedRouteSnapshot, state: RouterStateSnapshot) => {
6:   const alertService = inject(AlertService);
7:   const menuInfo = localStorage.getItem('menu');
8:   const menuPermisos = menuInfo ? JSON.parse(atob(menuInfo)) : null;
9:   const fullUrl = window.location.href;
10:   const url = new URL(fullUrl);
11:   const path = url.pathname;
12: 
13:   // Obtener parámetros de la ruta
14:   const params = route.params;
15: 
16:   if (menuPermisos != null) {
17:     // Pasar tanto la URL como los parámetros a la función de verificación
18:     if (checkUrlExists(menuPermisos, path, params)) {
19:       return true;
20:     }
21:   }
22: 
23:   alertService.showErrorAlert("No tiene permisos para realizar esta acción", "Acceso prohibido");
24:   return false;
25: };
26: 
27: // Recorrer el menú para verificar si la URL y los parámetros existen
28: function checkUrlExists(menuItems: any, targetUrl: string, params: any): boolean {
29:   return menuItems.some((item: any) => {
30:     // Verificar la URL y los parámetros
31:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
32:       return true;
33:     }
34:     if (item.Opciones && item.Opciones.length > 0) {
35:       return checkUrlExists(item.Opciones, targetUrl, params);
36:     }
37:     return false;
38:   });
39: }
40: 
41: // Verificar los parámetros de la ruta
42: function checkParams(expectedParams: any, actualParams: any): boolean {
43:   if (!expectedParams) {
44:     return true; // No se requieren parámetros específicos
45:   }
46:   for (let key in expectedParams) {
47:     if (expectedParams[key] !== actualParams[key]) {
48:       return false; // Un parámetro no coincide
49:     }
50:   }
51:   return true; // Todos los parámetros coinciden
52: }

