2: import { decrypt } from './../utils/util-encrypt';
3: 
4: @Injectable({
5:   providedIn: 'root',
6: })
7: export class UserService {
8:   constructor() {}
9: 
10:   // Método para obtener el persona_id desencriptado desde el localStorage
11:   public getPersonaId(): Promise<number> {
12:     return new Promise((resolve, reject) => {
13:       const strcryptedId = localStorage.getItem('persona_id');
14:       const strId = decrypt(strcryptedId);
15:       if (strId) {
16:         resolve(parseInt(strId, 10));
17:       } else {
18:         reject(new Error('No id found'));
19:       }
20:     });
21:   }
22: 
23:   // Método para decodificar la información del usuario almacenada
24:   private decodeUser(): any {
25:     const strUser = localStorage.getItem("user");
26:     if (strUser === null || strUser === "") {
27:       throw new Error("No user information found");
28:     } else {
29:       try {
30:         const strdecoded = atob(strUser);
31:         const parsed = JSON.parse(strdecoded);
32:         if (parsed.user && parsed.userService) {
33:           return parsed;
34:         } else {
35:           throw new Error("Incomplete user information");
36:         }
37:       } catch (error) {
38:         throw new Error("Invalid user information: " + error);
39:       }
40:     }
41:   }
42: 
43:   // Método para obtener los roles del usuario
44:   public getUserRoles(): Promise<string[]> {
45:     return new Promise((resolve, reject) => {
46:       try {
47:         const { user, userService } = this.decodeUser();
48:         const roleUser = typeof user.role !== 'undefined' ? user.role as string[] : [];
49:         const roleUserService = typeof userService.role !== 'undefined' ? userService.role as string[] : [];
50:         const combinedRoles = roleUser.concat(roleUserService).filter((data: string) => !data.includes('/'));
51:         const roles = Array.from(new Set(combinedRoles));
52:         resolve(roles);
53:       } catch (error) {
54:         reject(error);
55:       }
56:     });
57:   }
58: 
59:   // Método para obtener el email del usuario
60:   public getUserEmail(): Promise<string> {
61:     return new Promise((resolve, reject) => {
62:       try {
63:         const { user, userService } = this.decodeUser();
64:         if (user.email) {
65:           resolve(user.email);
66:         } else if (userService.email) {
67:           resolve(userService.email);
68:         } else {
69:           reject(new Error("No email found"));
70:         }
71:       } catch (error) {
72:         reject(error);
73:       }
74:     });
75:   }
76: 
77:   // Método para obtener el documento del usuario, compuesto o no
78:   public getUserDocument(compuesto: boolean = false): Promise<string> {
79:     return new Promise((resolve, reject) => {
80:       try {
81:         const { user, userService } = this.decodeUser();
82:         const documentToSearch = compuesto ? 'documento_compuesto' : 'documento';
83:         if (user[documentToSearch]) {
84:           resolve(user[documentToSearch]);
85:         } else if (userService[documentToSearch]) {
86:           resolve(userService[documentToSearch]);
87:         } else {
88:           reject(new Error("No document found"));
89:         }
90:       } catch (error) {
91:         reject(error);
92:       }
93:     });
94:   }
95: }

